VALUES
  ('00000000-0000-0000-0000-000000007701','00000000-0000-0000-0000-000000000000','authenticated','authenticated','owner-a.77@example.test','',now(),'{}','{}',now(),now()),
  ('00000000-0000-0000-0000-000000007702','00000000-0000-0000-0000-000000000000','authenticated','authenticated','owner-b.77@example.test','',now(),'{}','{}',now(),now());
SELECT * FROM app.bootstrap_first_owner('00000000-0000-0000-0000-000000007701','owner-a.77@example.test','Owner A Seventy Seven',decode('7777777777777777777777777777777777777777777777777777777777777777','hex'),'req-77','corr-77');
