VALUES ('Transfer Contractor','Transfer Contractor','USD','Asia/Singapore',(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007701'),(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007701'));
INSERT INTO app.users (id, auth_subject, email, user_type, status, is_active, created_by, updated_by)
VALUES ('10000000-0000-0000-0000-000000007702','00000000-0000-0000-0000-000000007702','owner-b.77@example.test','STAFF','ACTIVE',true,(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007701'),(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007701'));
INSERT INTO app.user_profiles (user_id, full_name, created_by, updated_by) VALUES ('10000000-0000-0000-0000-000000007702','Owner B',(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007701'),(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007701'));
INSERT INTO app.user_roles (user_id, role_code, assigned_by, is_active) VALUES ('10000000-0000-0000-0000-000000007702','owner_admin',(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007701'),true);

SELECT * FROM public.server_owner_create_financial_account('00000000-0000-0000-0000-000000007701','Transfer Source 77','CASH','USD');
SELECT * FROM public.server_owner_create_financial_account('00000000-0000-0000-0000-000000007701','Transfer Destination 77','BANK','USD','Bank 77','1234',NULL,true);
SELECT * FROM public.server_owner_create_financial_account('00000000-0000-0000-0000-000000007701','Transfer Other 77','CASH','USD');
SELECT * FROM public.server_owner_create_financial_account('00000000-0000-0000-0000-000000007701','Transfer SAR 77','CASH','SAR');
SELECT * FROM public.server_owner_create_opening_balance('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),100,DATE '2026-07-29','USD','source opening',NULL,'open-source-77');
SELECT * FROM public.server_owner_submit_opening_balance('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_events WHERE description='source opening'),1);
SELECT * FROM public.server_owner_approve_opening_balance('00000000-0000-0000-0000-000000007702',(SELECT id FROM app.financial_events WHERE description='source opening'),2);

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),25,'USD',DATE '2026-07-30',' ref-001 ',' private notes ') $$,'Owner creates account transfer draft');
SELECT results_eq($$ SELECT at.reference::text, at.notes, at.amount, at.currency_code, fe.event_type::text, fe.project_id IS NULL, fe.client_id IS NULL, ft.reporting_currency_code FROM app.account_transfers at JOIN app.financial_events fe ON fe.id=at.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE at.reference='REF-001' $$,$$ VALUES ('REF-001'::text,'private notes'::text,25::numeric,'USD'::bpchar,'ACCOUNT_TRANSFER'::text,true,true,'USD'::bpchar) $$,'draft stores normalized reference, private notes, contractor scope and reporting snapshot');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.financial_events fe ON fe.id=ft.financial_event_id WHERE fe.event_type='ACCOUNT_TRANSFER'),0,'draft transfer has no ledger entries');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),25,'USD',DATE '2026-07-30','REF-001',NULL) $$,'23505','Duplicate account transfer.','exact non-rejected duplicate denied');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),25,'USD',DATE '2026-07-30','REF-001',NULL) $$,'reversed direction is not duplicate');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),26,'USD',DATE '2026-07-30','REF-001',NULL) $$,'different amount is not duplicate');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),25,'USD',DATE '2026-07-31','REF-001',NULL) $$,'different date is not duplicate');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),5,'USD',DATE '2026-07-30',NULL,NULL) $$,'null reference transfer allowed once');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),5,'USD',DATE '2026-07-30',' ',NULL) $$,'blank reference similar transfer allowed again');
SELECT is((SELECT count(*)::integer FROM app.account_transfers WHERE reference IS NULL),2,'null/blank references avoid false duplicate positives');
SELECT ok((SELECT bool_and(fe.duplicate_fingerprint LIKE '%event_number=FE-%') FROM app.account_transfers at JOIN app.financial_events fe ON fe.id=at.financial_event_id WHERE at.reference IS NULL),'null-reference fingerprints include event number');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),1,'USD',DATE '2026-07-30',NULL,NULL) $$,'23514','Invalid account transfer.','same source and destination denied');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),0,'USD',DATE '2026-07-30',NULL,NULL) $$,'23514','Invalid account transfer.','zero amount denied');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer SAR 77'),1,'USD',DATE '2026-07-30',NULL,NULL) $$,'23514','Invalid account transfer.','mixed account currency denied');

SELECT throws_ok($$ UPDATE app.account_transfers SET amount=99 WHERE reference='REF-001' $$,'23514','Account transfers require trusted functions.','direct transfer update denied');
SELECT throws_ok($$ DELETE FROM app.account_transfers WHERE reference='REF-001' $$,'23514','Account transfers cannot be deleted.','direct transfer delete denied');
SELECT throws_ok($$ SELECT * FROM public.server_owner_update_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REF-001' AND notes='private notes'),0,(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),30,'USD',DATE '2026-07-30','REF-002','changed') $$,'40001','Account transfer version conflict.','stale update rejected');
SELECT lives_ok($$ SELECT * FROM public.server_owner_update_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REF-001' AND notes='private notes'),1,(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),30,'USD',DATE '2026-07-30','REF-002','changed') $$,'draft update works');
SELECT results_eq($$ SELECT at.amount, at.reference::text, at.notes, fe.version_number, ft.reporting_currency_code FROM app.account_transfers at JOIN app.financial_events fe ON fe.id=at.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE at.reference='REF-002' $$,$$ VALUES (30::numeric,'REF-002'::text,'changed'::text,2,'USD'::bpchar) $$,'draft update preserves reporting snapshot and increments parent version');
UPDATE app.contractor_profiles SET default_reporting_currency_code='SAR' WHERE singleton_key=1;
SELECT is((SELECT ft.reporting_currency_code FROM app.account_transfers at JOIN app.financial_transactions ft ON ft.financial_event_id=at.financial_event_id WHERE at.reference='REF-002'),'USD'::bpchar,'later contractor reporting-currency change does not alter existing transfer');
UPDATE app.contractor_profiles SET default_reporting_currency_code='USD' WHERE singleton_key=1;

SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REF-002'),2) $$,'Owner submits transfer');
SELECT results_eq($$ SELECT fe.status::text, ft.status::text, fe.version_number FROM app.account_transfers at JOIN app.financial_events fe ON fe.id=at.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE at.reference='REF-002' $$,$$ VALUES ('SUBMITTED'::text,'SUBMITTED'::text,3) $$,'submit moves event and transaction to submitted');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'))),100::numeric,'submitted transfer has no source balance effect');
SELECT throws_ok($$ SELECT * FROM public.server_owner_approve_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REF-002'),3) $$,'42501','Account transfer requires different Owner approval.','self approval denied');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_account_transfer('00000000-0000-0000-0000-000000007702',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REF-002'),3) $$,'different Owner approves and posts');
SELECT results_eq($$ SELECT fe.status::text, ft.status::text, fe.version_number, fe.approved_by=(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007702'), ft.posted_by=(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007702') FROM app.account_transfers at JOIN app.financial_events fe ON fe.id=at.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE at.reference='REF-002' $$,$$ VALUES ('APPROVED'::text,'POSTED'::text,4,true,true) $$,'approval records different Owner and terminal statuses');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.account_transfers at ON at.financial_event_id=ft.financial_event_id WHERE at.reference='REF-002'),2,'approval inserts exactly two ledger entries');
SELECT results_eq($$ SELECT le.line_no, CASE WHEN la.financial_account_id=(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77') THEN 'DESTINATION-ASSET' WHEN la.financial_account_id=(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77') THEN 'SOURCE-ASSET' ELSE la.code::text END, le.debit_amount, le.credit_amount, le.project_id IS NULL, le.client_id IS NULL FROM app.ledger_entries le JOIN app.ledger_accounts la ON la.id=le.ledger_account_id JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.account_transfers at ON at.financial_event_id=ft.financial_event_id WHERE at.reference='REF-002' ORDER BY le.line_no $$,$$ VALUES (1,'DESTINATION-ASSET'::text,30::numeric,0::numeric,true,true),(2,'SOURCE-ASSET'::text,0::numeric,30::numeric,true,true) $$,'ledger debits destination asset and credits source asset with null Project/Client');
SELECT results_eq($$ SELECT le.reporting_debit_amount, le.reporting_credit_amount, le.exchange_rate_id IS NULL FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.account_transfers at ON at.financial_event_id=ft.financial_event_id WHERE at.reference='REF-002' ORDER BY le.line_no $$,$$ VALUES (30::numeric,0::numeric,true),(0::numeric,30::numeric,true) $$,'same-currency reporting values net to zero without exchange snapshot');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'))),70::numeric,'source account decreases by transfer amount');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'))),30::numeric,'destination account increases by transfer amount');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Other 77'))),0::numeric,'unrelated account unchanged');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balances_by_currency('00000000-0000-0000-0000-000000007701') WHERE currency_code='USD'),100::numeric,'combined USD financial-asset total preserved');
SELECT is_empty($$ SELECT project_id FROM public.server_owner_project_expense_totals('00000000-0000-0000-0000-000000007701',gen_random_uuid()) $$,'transfer has no Project-balance effect');
SELECT throws_ok($$ SELECT * FROM public.server_owner_update_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REF-002'),4,(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),31,'USD',DATE '2026-07-30','REF-003','after approve') $$,'23514','Account transfer cannot be updated.','approved transfer cannot be updated through workflow');
SELECT throws_ok($$ UPDATE app.ledger_entries SET memo='tamper' WHERE memo='Account transfer destination debit' $$,'23514','Posted ledger entries are immutable.','transfer ledger entries immutable');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_account_transfer('00000000-0000-0000-0000-000000007702',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REF-002'),4) $$,'approval retry is idempotent');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.account_transfers at ON at.financial_event_id=ft.financial_event_id WHERE at.reference='REF-002'),2,'approval retry does not duplicate ledger entries');
SELECT is((SELECT count(*)::integer FROM app.activity_logs WHERE action='account_transfer_transaction_posted'),1,'approval retry does not duplicate posting activity');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),200,'USD',DATE '2026-08-01','NEG-OK',NULL) $$,'negative-balance policy allows oversized draft');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT financial_event_id FROM app.account_transfers WHERE reference='NEG-OK'),1) $$,'negative-balance transfer submitted');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_account_transfer('00000000-0000-0000-0000-000000007702',(SELECT financial_event_id FROM app.account_transfers WHERE reference='NEG-OK'),2) $$,'negative-balance transfer approved with no sufficient-balance enforcement');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'))),-130::numeric,'source account may become negative from posted transfers');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balances_by_currency('00000000-0000-0000-0000-000000007701') WHERE currency_code='USD'),100::numeric,'combined total remains preserved even with negative source');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_reversal('00000000-0000-0000-0000-000000007701',(SELECT ft.id FROM app.financial_transactions ft JOIN app.account_transfers at ON at.financial_event_id=ft.financial_event_id WHERE at.reference='REF-002'),DATE '2026-08-02','reverse transfer','reverse transfer') $$,'existing full reversal can target posted transfer');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_reversal('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_events WHERE event_type='REVERSAL' AND description='reverse transfer'),1) $$,'transfer reversal submitted');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_reversal('00000000-0000-0000-0000-000000007702',(SELECT id FROM app.financial_events WHERE event_type='REVERSAL' AND description='reverse transfer'),2) $$,'transfer reversal approved');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'))),-100::numeric,'full reversal restores the transfer source effect exactly');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'))),200::numeric,'full reversal restores the transfer destination effect exactly');

UPDATE app.contractor_profiles SET default_reporting_currency_code='SAR' WHERE singleton_key=1;
SELECT * FROM public.server_owner_create_exchange_rate('00000000-0000-0000-0000-000000007701',DATE '2026-08-03','USD','SAR',3.75);
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),10,'USD',DATE '2026-08-03','RATE-SNAP',NULL) $$,'new transfer snapshots current SAR contractor reporting currency at draft');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT financial_event_id FROM app.account_transfers WHERE reference='RATE-SNAP'),1) $$,'rate snapshot transfer submitted');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_account_transfer('00000000-0000-0000-0000-000000007702',(SELECT financial_event_id FROM app.account_transfers WHERE reference='RATE-SNAP'),2) $$,'rate snapshot transfer approved with manual transaction-date rate');
SELECT is((SELECT count(DISTINCT exchange_rate_id)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.account_transfers at ON at.financial_event_id=ft.financial_event_id WHERE at.reference='RATE-SNAP'),1,'both transfer lines share one exchange-rate snapshot');
SELECT results_eq($$ SELECT sum(reporting_debit_amount), sum(reporting_credit_amount) FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.account_transfers at ON at.financial_event_id=ft.financial_event_id WHERE at.reference='RATE-SNAP' $$,$$ VALUES (37.50::numeric,37.50::numeric) $$,'converted reporting amounts balance exactly');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),1,'USD',DATE '2026-08-04','REJECT-ME',NULL) $$,'rejection draft created');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REJECT-ME'),1) $$,'rejection draft submitted');
SELECT throws_ok($$ SELECT * FROM public.server_owner_reject_account_transfer('00000000-0000-0000-0000-000000007702',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REJECT-ME'),2,'') $$,'23514','Rejection reason is required.','blank rejection denied');
SELECT lives_ok($$ SELECT * FROM public.server_owner_reject_account_transfer('00000000-0000-0000-0000-000000007702',(SELECT financial_event_id FROM app.account_transfers WHERE reference='REJECT-ME'),2,'raw private reason') $$,'submitted transfer rejected');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_account_transfer('00000000-0000-0000-0000-000000007701',(SELECT id FROM app.financial_accounts WHERE name='Transfer Source 77'),(SELECT id FROM app.financial_accounts WHERE name='Transfer Destination 77'),1,'USD',DATE '2026-08-04','REJECT-ME',NULL) $$,'replacement after rejection is allowed');
SELECT ok(NOT EXISTS (SELECT 1 FROM app.activity_logs WHERE action LIKE 'account_transfer_%' AND (previous_values::text ILIKE '%private notes%' OR new_values::text ILIKE '%private notes%' OR metadata::text ILIKE '%private notes%' OR previous_values::text ILIKE '%raw private reason%' OR new_values::text ILIKE '%raw private reason%' OR metadata::text ILIKE '%raw private reason%' OR previous_values::text ILIKE '%REF-002%' OR new_values::text ILIKE '%REF-002%' OR metadata::text ILIKE '%REF-002%')),'activity logs omit private notes, rejection reason and raw reference');

SELECT * FROM finish();
ROLLBACK;
